      const tf = (lab, key, area) => '<label class="field"><span>' + lab + '</span>' + (area ? '<textarea id="' + ID(inst, 'ws' + key) + '" data-agf="ws.' + key + '" rows="4">' + esc(p[key]) + '</textarea>' : '<input id="' + ID(inst, 'ws' + key) + '" data-agf="ws.' + key + '" value="' + esc(p[key]) + '">') + '</label>';
