        '<main class="a-body"><div class="a-view a-v-' + esc(st.view) + (inst._enter ? ' a-enter' : '') + '">' + body + '</div></main></div></div>' +
        (m ? '<div class="a-modal-back' + (inst._menter ? ' a-enter' : '') + '"><div class="a-modal" role="dialog" aria-modal="true">' + m + '</div></div>' : '') + '</div>';
