      const g = gOf(b), p = P(b.propertyId), t = s.today, c = b.checkin, th = BB.q.threadFor(b.id);
      const n = nightsOf(b), stays = BB.q.stays(g.id), life = BB.q.lifetime(g.id);
      const canCancel = b.status === 'confirmed' && b.checkOut > t;
      // price
