    keydown(ev, inst) { if (ev.key === 'Enter' && (ev.metaKey || ev.ctrlKey) && ev.target.matches('[data-ibdraft]')) { ev.preventDefault(); const cur = BB.q.thread(inst.st.id) || sortedThreads()[0]; if (cur) send(inst, cur, inst.st.ib_draft || ''); } },
