            if (r2.status === 401 || r2.status === 403) throw err(400, 'Nuki did not accept that token. Check it has the "Manage smart locks" permission.');
            if (!r2.ok) throw err(502, "Nuki answered with error " + r2.status + ". Try again in a minute.");
            locks = (await r2.json()).map((x) => ({ id: String(x.smartlockId), name: String(x.name || "Lock").slice(0, 60) }));
