            i.locks = locks;
            i.detail = locks.length + (locks.length === 1 ? " lock" : " locks") + " found in your Nuki account";
            BB.log("sync", "Nuki smart locks", "Connected Nuki. Found " + locks.length + (locks.length === 1 ? " lock." : " locks.") + " Pick the lock for each home in Website & SEO, Guest details.", "lock");
            BB.store.commit({ type: "integration", id: "lock" });
